    <script type="text/javascript">
        $(document).ready(function () {
            var val = localStorage.getItem("lenguageval")
            if (val == 1) {
                $("#txtCulture").text('हिंदी');

            }
            else {

                $("#txtCulture").text('English');

            }

            $("#txtCulture").click(function () {
                if ($("#txtCulture").text() == 'English') {
                    var cultureSelectedValue = 1;
                    //alert("IF    " + cultureSelectedValue);
                    $.ajax({
                        type: "POST",
                        url: '/Home/ChangeCurrentCulture',
                        data: { cid: cultureSelectedValue },
                        success: function (result) {

                            localStorage.setItem("lenguageval", 1);
                            location.reload(true);
                        },
                        error: function (err) {
                            alert(err);
                        }
                    });
                }
                else {
                    var cultureSelectedValue = 0;
                    //alert("ELSE    " + cultureSelectedValue);
                    $.ajax({
                        type: "POST",
                        url: '/Home/ChangeCurrentCulture',
                        data: { cid: cultureSelectedValue },
                        success: function (result) {

                            localStorage.setItem("lenguageval", 0);
                            location.reload(true);
                        },
                        error: function (err) {
                            alert(err);
                        }
                    });
                }
            })

            $(".autoplay").slick({
                slidesToShow:4,
                autoplay: true,
                autoplaySpeed: 3000,
                responsive: [
                    { breakpoint: 1024, settings: { slidesToShow: 3, slidesToScroll: 3, infinite: true, dots: true } },
                    { breakpoint: 600, settings: { slidesToShow: 2, slidesToScroll: 2 } },
                    { breakpoint: 480, settings: { slidesToShow: 1, slidesToScroll: 1 } }]
            });
            // Home page slick slider in project section
            $(".center").slick({
                dots: false,
                infinite: true,
                centerMode: true,
                slidesToShow: 3,
                slidesToScroll: 1,
                autoplay: true,
                autoplaySpeed: 3000,
                responsive: [
                    { breakpoint: 1024, settings:{ slidesToShow: 3, slidesToScroll: 3, infinite: true, dots: true } },
                    { breakpoint: 600, settings: { slidesToShow: 2, slidesToScroll: 2 } },
                    { breakpoint: 480, settings: { slidesToShow: 1, slidesToScroll: 1 } }]
            });

            $(".footer-icon-menu").slick({
                dots: false,
                infinite: true,
                centerMode: false,
                slidesToShow: 6,
                slidesToScroll: 1,
                autoplay: true,
                autoplaySpeed: 3000,
                responsive: [
                    { breakpoint: 1024, settings: { slidesToShow: 3, slidesToScroll: 3, infinite: true, dots: false } },
                    { breakpoint: 600, settings: { slidesToShow: 2, slidesToScroll: 2 } },
                    { breakpoint: 480, settings: { slidesToShow: 1, slidesToScroll: 1 } }]
            });
        });
